insert into questions (quiz_id, question_text, options, correct_option, explanation, sort_order, difficulty, statement_id) values
((select id from quizzes where topic_id='1fb446d5-10eb-407d-9d60-e5ca030eeb1c' limit 1), 'A sector of a circle of radius 6 cm has angle 1.2 radians. Find its area.', '["10.8 cm²","21.6 cm²","7.2 cm²","43.2 cm²"]'::jsonb, 1, 'Area = ½r²θ = ½ × 6² × 1.2 = ½ × 36 × 1.2 = 21.6 cm².', 100, 'exam', '590b6ceb-ceb4-4e33-a2a5-9a3d6c396300'),
((select id from quizzes where topic_id='0bea2707-6672-4f20-8be1-a847f759f0ca' limit 1), 'Solve 5(2x − 3) = 3x + 11.', '["x = 4","x = 2","x = 16/7","x = 26/7"]'::jsonb, 3, 'Expand: 10x − 15 = 3x + 11, so 7x = 26 and x = 26/7.', 100, 'exam', '884eec33-f615-411d-b184-6e07885e7973'),
((select id from quizzes where topic_id='0f4bcc9a-e4a0-4c6a-ae8d-2354b6190d2e' limit 1), 'Find (3; −2) + (−1; 5) as a column vector.', '["(4; −7)","(2; 3)","(2; −7)","(−3; 2)"]'::jsonb, 1, 'Add the components: (3 + (−1); −2 + 5) = (2; 3).', 100, 'exam', '72a12ab0-14d1-4a48-a248-f143bd40fb0e'),
((select id from quizzes where topic_id='6111cf0b-63cc-4804-a218-1b16e82da4f3' limit 1), 'A right-angled triangle has hypotenuse 10 cm and one angle 30°. Find the side opposite the 30° angle.', '["8.66 cm","5 cm","10 cm","3.46 cm"]'::jsonb, 1, 'sin 30° = opposite / hypotenuse, so opposite = 10 × sin 30° = 10 × 0.5 = 5 cm.', 100, 'exam', '33584833-368d-47fe-9688-e4e1913896c1'),
((select id from quizzes where topic_id='8f5f82ea-a53d-45ad-afb8-87e365ba6342' limit 1), 'In triangle ABC, a = 5 cm, b = 7 cm and c = 8 cm. Find angle C, to 1 decimal place.', '["60.0°","98.2°","81.8°","45.6°"]'::jsonb, 2, 'cos C = (a² + b² − c²) / 2ab = (25 + 49 − 64) / 70 = 1/7, so C = arccos(1/7) = 81.8°.', 100, 'exam', '48aacf94-b819-4a50-a520-431b5e6d4568');
